    update questions set media = $q${"clip":{"url":"https://audio-cdn.tarteel.ai/quran/surah/husary/murattal/mp3/105.mp3","start_ms":28640,"end_ms":33870}}$q$::jsonb where position = 3 and homework_id = (select id from homeworks where number = 8);
